import boto3
from typing import List, Dict

def get_text(block: Dict, block_map: Dict[str, Dict]) -> str:
    text = ''
    if 'Relationships' in block:
        for relationship in block['Relationships']:
            if relationship['Type'] == 'CHILD':
                for child_id in relationship['Ids']:
                    child = block_map[child_id]
                    if child['BlockType'] == 'WORD':
                        text += child['Text'] + ' '
    return text.strip()

def extract_tables(document_path: str) -> List[Dict[str, List[List[str]]]]:
    client = boto3.client('textract')
    with open(document_path, 'rb') as file:
        document = file.read()
    response = client.analyze_document(
        Document={'Bytes': document},
        FeatureTypes=['TABLES']
    )
    blocks = response['Blocks']
    block_map = {block['Id']: block for block in blocks}
    tables = []
    for block in blocks:
        if block['BlockType'] == 'TABLE':
            cells = []
            if 'Relationships' in block:
                for relationship in block['Relationships']:
                    if relationship['Type'] == 'CHILD':
                        for cell_id in relationship['Ids']:
                            cell_block = block_map[cell_id]
                            if cell_block['BlockType'] == 'CELL':
                                text = get_text(cell_block, block_map)
                                cells.append({
                                    'row_idx': cell_block['RowIndex'],
                                    'col_idx': cell_block['ColumnIndex'],
                                    'row_span': cell_block.get('RowSpan', 1),
                                    'col_span': cell_block.get('ColumnSpan', 1),
                                    'text': text
                                })
            if cells:
                max_row = max(c['row_idx'] + c['row_span'] - 1 for c in cells)
                max_col = max(c['col_idx'] + c['col_span'] - 1 for c in cells)
                grid: List[List[str]] = [['' for _ in range(max_col)] for _ in range(max_row)]
                for cell in cells:
                    r_start = cell['row_idx'] - 1
                    c_start = cell['col_idx'] - 1
                    grid[r_start][c_start] = cell['text']
                rows = grid
                tables.append({'rows': rows})
    return tables
